    "fr": "<p><b>Le cinéma Starlight est de retour !</b></p><p>Après trois mois de rénovation, le cinéma Starlight d'Orchard Road rouvrira le vendredi 6 juin. Le bâtiment compte désormais trois salles au lieu d'une, et chaque fauteuil a été remplacé par un modèle plus large et inclinable. Les billets pour toutes les séances de la première semaine ne coûtent que 5 $, et les 200 premiers spectateurs de chaque jour recevront un sachet de pop-corn gratuit. Notre film d'ouverture sera le documentaire primé <i>Rivers of Light</i>. Les billets sont en vente à la billetterie ou en ligne sur www.starlightcinema.example. Nous espérons vous y voir !</p>"
