    "fr": "<p>De : Laura Chen, ressources humaines. À : Kenji Mori. Date : 28 octobre. Objet : votre première semaine chez Dalton Engineering.</p><p>Monsieur Mori, bienvenue chez Dalton Engineering ! Nous sommes ravis que vous rejoigniez notre équipe de conception comme coordinateur de projet le lundi 4 novembre. Votre séance d'accueil commencera à 9 h 00 en salle 3B, au troisième étage. Veuillez apporter une pièce d'identité avec photo en cours de validité et les formulaires signés que nous vous avons envoyés la semaine dernière. Les formulaires doivent être remis avant que vous puissiez recevoir votre badge d'accès au bâtiment.</p><p>Pendant la matinée, vous rencontrerez votre responsable, Mme Alicia Torres, et ferez le tour des bureaux. Le déjeuner sera offert par l'entreprise, et vous aurez l'après-midi pour installer votre poste de travail avec l'aide du service informatique.</p><p>Comme le stationnement près du bureau est limité, nous encourageons les nouveaux salariés à utiliser la navette qui part de la gare centrale toutes les quinze minutes. Si vous préférez venir en voiture, répondez à ce courriel avant le 1er novembre afin que nous puissions vous réserver une place sur le parking visiteurs.</p><p>Nous avons hâte de vous voir !</p>"
