    "fr": "<p>De : Naomi Fischer, conservatrice. À : Paul Delacroix. Date : 12 mars. Objet : votre prêt des tableaux de port.</p><p>Monsieur Delacroix, merci de votre lettre concernant les tableaux de port que votre famille conserve depuis trois générations. Le conseil d'administration du musée maritime de Cranmore s'est réuni hier et, j'ai le plaisir de vous le dire, a voté l'acceptation de votre généreuse offre de prêt de longue durée. Une fois les tableaux sous notre garde, notre équipe de restauration devra examiner chacun d'eux, car plusieurs toiles montrent des signes de vieillissement. L'équipe estime que ce travail prendra environ huit semaines et sera réalisé aux frais du musée.</p><p>Nous aimerions dévoiler la collection lors d'une exposition spéciale l'automne prochain, et nous espérons que vous et votre famille y assisterez en invités d'honneur. D'ici là, je vous serais reconnaissante de nous envoyer tous documents, tels que des reçus ou des lettres, qui pourraient nous aider à retracer l'histoire des tableaux. Notre partenaire d'assurance, Harbor Mutual, couvrira la valeur estimée complète de chaque œuvre pendant la durée du prêt.</p><p>Cordialement, Naomi Fischer, conservatrice, musée maritime de Cranmore.</p>"
