    "fr": "<p><b>Document 1 : itinéraire.</b> Wanderline Travel Services. Préparé pour : Dr Lena Okoye ; par Marta Zaleski, conseillère voyages ; réf. WL-40817. Mardi 8 avril : vol Skyline Air 482, départ de Boston 8 h 15, arrivée à Seattle 11 h 20. Voiture de location Ridgeway : retrait à l'aéroport, voiture compacte, 42 $ par jour ; retour le vendredi 11 avril à 14 h 00. Hôtel Harborview : arrivée, 3 nuits, 149 $ la nuit ; départ le vendredi 11 avril. Jeudi 10 avril : Pacific Technology Forum, séance « La protection des données en pratique », 14 h 00, salle 3. Vendredi 11 avril : atelier « Construire un programme de protection des données », de 9 h 00 à 11 h 30, salle 5. Vol Skyline Air 485 : départ de Seattle 15 h 30, arrivée à Boston 23 h 55.</p><p><b>Document 2 : courriel.</b> De Lena Okoye à Marta Zaleski, le 25 mars. Merci pour cet itinéraire clair. Malheureusement, les organisateurs du forum viennent de m'informer que mon atelier du 11 avril aura désormais lieu de 13 h à 16 h au lieu du matin. Je ne pourrai donc pas prendre le vol de 15 h 30 ce jour-là. Pourriez-vous me réserver un vol plus tardif le soir du 11 avril ? Je vous serais aussi reconnaissante de modifier l'heure de retour de ma voiture de location, car j'en aurai besoin jusqu'après la fin de l'atelier. La réservation d'hôtel n'a pas à changer. Merci de m'indiquer le nouveau numéro de vol et le montant d'éventuels frais de modification dès que possible.</p>"
