    "fr": "<p><b>Document 1 : courriel.</b> De Priscilla Grant, coordinatrice, à tous les participants inscrits, le 20 octobre. Objet : information importante pour le Coastal Business Forum. Chers participants, merci de vous être inscrits au Coastal Business Forum, qui aura lieu le jeudi 6 novembre et le vendredi 7 novembre au Harbor Convention Hall. En raison d'une fuite d'eau dans l'aile est, la salle E2 ne peut pas être utilisée ; la séance de jeudi sur le marketing numérique a donc été déplacée en salle W1. Toutes les autres séances restent prévues comme indiqué. L'accueil ouvre à 8 h 00 dans le hall principal les deux jours, et les badges nominatifs sont obligatoires pour entrer dans toutes les séances. Le déjeuner est compris le jeudi seulement. Le vendredi, les participants peuvent acheter leur déjeuner au Garden Café. Un plan du bâtiment est joint pour vous aider à vous orienter. Nous nous réjouissons de vous voir.</p><p><b>Document 2 : programme.</b> Coastal Business Forum, jeudi 6 novembre. 9 h 00 : discours d'ouverture, grande salle. 10 h 00 : marketing numérique pour les petites entreprises, salle E2. 11 h 30 : gérer des équipes à distance, salle W2. 12 h 30 : déjeuner (compris dans l'inscription), Garden Café. 13 h 30 : bases de la planification financière, salle E1. 15 h 00 : table ronde de clôture, grande salle.</p><p><b>Document 3 : plan.</b> Harbor Convention Hall, rez-de-chaussée. Le Garden Café est au nord-est, juste au-dessus de la salle E1. Les salles W1 et W2 sont dans l'aile ouest, E1 et E2 dans l'aile est, autour de la grande salle. Le hall principal (accueil et entrée) est au sud ; les toilettes sont au sud-ouest.</p>"
