    "fr": "<p><b>Clearwater Home Goods, demande de retour.</b> Nom du client : Rosa Delgado. Numéro de commande : CH-70419. Date de livraison : 9 octobre. Date de la demande : 14 octobre. Article : lampe de table en céramique, modèle L-204. Motif du retour : endommagée pendant le transport (pied fissuré). Solution souhaitée : remplacement.</p><p>Les retours sont acceptés dans les 30 jours suivant la livraison. Une étiquette d'expédition prépayée sera envoyée par courriel. Les remboursements sont effectués dans les 7 jours ouvrables suivant la réception de l'article. Les remplacements sont expédiés dans les 3 jours ouvrables.</p>"
