    "fr": "<p><b>Le marché fermier restera ouvert jusqu'en décembre.</b> GREENFIELD (18 septembre). Le marché fermier de Greenfield, qui se tient le samedi matin sur la place Pine depuis 2009, ne fermera plus à la fin octobre. La responsable du marché, Olivia Reyes, a déclaré que cette décision faisait suite à une enquête dans laquelle 64 % des clients réguliers avaient demandé une saison plus longue.</p><p>À partir du 1er novembre, le marché se tiendra à l'intérieur, dans le bâtiment du Vieux Moulin, qui est chauffé et peut accueillir 25 exposants, contre 40 sur la place. Les exposants souhaitant participer doivent déposer leur candidature avant le 10 octobre. Mme Reyes a précisé que la priorité sera donnée à ceux qui vendent des produits alimentaires cultivés ou fabriqués à moins de 80 kilomètres de Greenfield. Le stationnement au moulin sera gratuit.</p>"
