    "fr": "<p>Hartwell Community Theater, 12 Orchard Street, Hartwell, 14 novembre. Cher M. Abernathy,</p><p>Merci pour votre généreux don de 500 $ au Hartwell Community Theater. Votre contribution servira à remplacer le système d'éclairage de notre grande salle, utilisé depuis plus de vingt ans. Les travaux devraient commencer en janvier, lorsque le théâtre ferme pour sa pause hivernale annuelle. En tant que donateur de niveau Argent, vous êtes invité à une visite privée du nouveau matériel le 8 février, et vous recevrez deux places gratuites pour notre production de printemps, <i>The Lighthouse Keeper</i>. Pour réserver vos places, veuillez appeler la billetterie au 555-0143 avant le 1er mars.</p><p>Cordialement, Nadia Sorensen, directrice du développement.</p>"
