    "fr": "<p><b>Lucy Chen (14 h 03)</b> : Hector, une cliente de Dayton dit que les 40 chaises de bureau qu'elle a commandées sont arrivées en gris au lieu de noir. Peux-tu vérifier l'entrepôt ?</p><p><b>Hector Silva (14 h 06)</b> : Je viens de regarder. Nous avons 15 chaises noires ici, et 25 autres arrivent jeudi. Je pourrais expédier les 15 aujourd'hui.</p><p><b>Lucy Chen (14 h 07)</b> : Ça marche. Les 25 autres peuvent-elles partir vendredi ?</p><p><b>Jin Park (14 h 09)</b> : Je peux organiser un enlèvement vendredi, mais la commande doit être saisie avant 16 h 00.</p><p><b>Lucy Chen (14 h 10)</b> : Je la saisis tout de suite.</p><p><b>Hector Silva (14 h 11)</b> : Alors j'étiquette les chaises grises pour le retour.</p><p><b>Jin Park (14 h 12)</b> : Prépare-les pour vendredi midi, s'il te plaît. Le camion part à 12 h 30.</p>"
