    "fr": "<p>De : Greta Lindqvist, directrice des opérations. À : l'équipe Marketing. Date : 12 mai. Objet : déménagement au quatrième étage.</p><p>Chers collègues, comme vous le savez, notre service déménagera du deuxième au quatrième étage du bâtiment Calder le samedi 6 juin. Ce déménagement vise à nous rapprocher de l'équipe Ventes, avec laquelle nous travaillons tous les jours.</p><p>Des déménageurs professionnels transporteront tous les meubles et le matériel, mais chacun de vous est responsable de l'emballage de ses affaires personnelles. Des cartons seront livrés à vos bureaux le lundi 1er juin. Veuillez étiqueter chaque carton avec votre nom et votre nouveau numéro de bureau, que vous trouverez sur le plan de bureaux joint.</p><p>Vous n'avez pas besoin d'être présents pendant le déménagement. Toutefois, toute personne qui prévoit de venir le samedi doit en informer Mme Okafor avant le 23 mai, car son équipe devra organiser l'accès au bâtiment. Notez que le nouvel étage compte moins d'imprimantes ; l'informatique en installera donc deux supplémentaires avant le déménagement.</p><p>Merci de votre coopération.</p>"
