    "fr": "<p><b>Emprunter à la bibliothèque de Maple Ridge.</b> La carte de bibliothèque est gratuite pour les habitants de Maple Ridge et du comté voisin de Cedar. Les nouveaux membres doivent présenter une pièce d'identité avec photo et un justificatif de domicile.</p><p>Les livres peuvent être empruntés pendant 21 jours et renouvelés deux fois en ligne, sauf si un autre membre les a réservés. Les DVD et livres audio peuvent être gardés 7 jours et ne sont pas renouvelables.</p><p>Pénalités de retard : 25 centimes par jour pour les livres et 50 centimes par jour pour les DVD, avec un maximum de 10 $ par article.</p><p>Livres numériques : les membres qui utilisent l'application de la bibliothèque peuvent en emprunter cinq à la fois.</p><p>Salles de réunion : les membres peuvent réserver une salle pour deux heures au maximum. Veuillez faire votre demande au moins une semaine à l'avance.</p>"
