    "fr": "<p>NOTE DE SERVICE. À : tout le personnel de production. De : Harold Becker, directeur d'usine. Date : 25 août. Objet : nouvelles lunettes de protection.</p><p>À partir du 8 septembre, tous les employés qui travaillent sur la chaîne de production doivent porter les nouvelles lunettes de protection distribuées par le service sécurité. Ces lunettes remplacent l'ancien modèle, que plusieurs ouvriers trouvaient inconfortable pendant les longs postes. Chaque employé doit retirer une paire à la réserve entre le 1er et le 5 septembre. La réserve est ouverte de 7 h 00 à 15 h 30. Les employés qui perdent leurs lunettes recevront un remplacement gratuit ; tout remplacement supplémentaire coûtera 12 $.</p><p>Merci de nous aider à garder l'usine sûre.</p>"
