    "fr": "<p><b>Document 1, coupon.</b> Lakeshore Grill. Offre du lundi : 20 % de réduction sur votre addition de nourriture (boissons non comprises). Valable le lundi uniquement, jusqu'au 31 décembre. Minimum de deux convives. Non cumulable avec d'autres offres. Présentez ce coupon avant de commander. 22 Pier Road, Lakeshore.</p><p><b>Document 2, courriel.</b> De : Owen Barlow. À : info@lakeshoregrill.example. Date : 10 décembre. Objet : coupon du lundi. Madame, Monsieur, lundi dernier, 7 décembre, mon épouse et moi avons dîné dans votre restaurant et avons présenté le coupon de votre publicité. Notre addition était de 96 $, dont 24 $ de boissons. Le serveur a dit que la réduction serait appliquée, mais le total final ne montrait qu'une déduction de 9,60 $. Je pense que le montant aurait dû être plus élevé.</p><p>J'ai gardé mon reçu et je vous serais reconnaissant de corriger l'erreur. Je tiens aussi à dire que la nourriture et le service étaient excellents. Cordialement, Owen Barlow.</p>"
