    "fr": "<p><b>Document 1, programme.</b> Greenway Software, programme de formation du printemps. Initiation aux tableurs : mardi 14 avril, 9 h à 12 h, salle 2. Bases de l'analyse de données : mercredi 15 avril, 13 h à 16 h, salle 4. Prise de parole en public : jeudi 16 avril, 9 h à 11 h, salle 2. Planification de projet : vendredi 17 avril, 10 h à 15 h (déjeuner compris), salle 3. Inscription avant le 8 avril. Une session est annulée si moins de six personnes s'inscrivent. Apportez un ordinateur portable à l'initiation aux tableurs et aux bases de l'analyse de données.</p><p><b>Document 2, courriel.</b> De : Yusuf Demir. À : service formation. Date : 6 avril. Objet : sessions de printemps. Madame, Monsieur, la session du 15 avril m'intéresse, mais mon vol depuis Chicago n'atterrira qu'à 15 h ce jour-là ; j'en manquerais donc la plus grande partie. Cette session sera-t-elle proposée de nouveau plus tard dans l'année ?</p><p>J'aimerais aussi assister à la session du 17 avril, mais je ne connaîtrai pas mes dates de voyage avant le 10 avril. Je sais que la date limite d'inscription est le 8 avril, mais je vous serais reconnaissant de me réserver une place jusqu'à ce que je confirme.</p><p>Enfin, je travaille habituellement sur une tablette plutôt que sur un ordinateur portable. Pouvez-vous me dire si une tablette serait acceptable ? Cordialement, Yusuf Demir.</p>"
